// ████ FROZEN — TEMPLATE v3 (quotation). DO NOT EDIT THIS FILE (nor api/_bp-docs-logo-v3.js). ████
//
// A quotation is rendered from its stored data every time it is opened, so a change here changes
// every v3 quotation ever issued. tests/bp-docs-v3-frozen.test.mjs pins this file and its output
// byte for byte. A change to the design, the CSS or the wording is a NEW template (v4): copy this
// file, change the copy, register it in api/_bp-docs.js. Callers never import this file: they go
// through templateForVersion() in api/_bp-docs.js.
//
// Business Partner — the quotation in the PERMANENT identity (owner decision 2026-10-29):
// the sales team's approved template (docs/sales/templates/REV-quote-template-bilingual.html and
// its standard REV-quote-design-standard.md on claude/sales-team-under-badr), generalised.
//
//   • A4 landscape (1123×794), IVORY letterhead paper: header (logo, bilingual title, navy rule),
//     footer (national address · contact + page number «n / N» · faded logo).
//   • Arabic on the RIGHT, English on the LEFT, rows aligned (one shared table / flex rows).
//   • Navy + the palette of the standard only; IBM Plex Sans Arabic / Playfair Display / IBM Plex Mono.
//   • Prices before 15% VAT; government fees separate; no word «draft» inside the client's paper.
//
// Pages: cover · other Business Partner services · price · scope · client requirements and
// exclusions · term, payment and conditions · signatures · back cover (contact + bank transfer).
// Adaptation (the template is written for the REV business-development packages): an ordinary order
// prints its own lines in the price table and the scope of each service; the package comparison
// and the revenue model appear ONLY when the order carries a REV-LAUNCH / REV-GROWTH / REV-PRO line.
//
// This file prices nothing: amounts are the quotation's own lines (priced from the catalogue by SKU
// when it was issued), formatted. Everything it needs beyond the lines (the services' scope text,
// the package figures, the company) is passed in `q.doc` — a snapshot stored with the quotation when
// it was issued — so reading an old quotation later never changes what it says.
//
// Deterministic by construction: no clock, no random; dates are formatted by hand (Riyadh time, Latin
// digits) and numbers with the fixed "en-US" locale.
// Underscore-prefixed: a module, not a serverless function (the plan caps them at 12).
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { LEGAL_NAME, LEGAL_NAME_EN, UNIFIED_NUMBER, VAT_NUMBER, BANK } from "./_identity.js";
import { LOGO_V3_PNG_B64 } from "./_bp-docs-logo-v3.js";

const RLM = "‏";
const env = (k) => String(process.env[k] || "").trim();
const esc = (v) => String(v == null ? "" : v).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const round2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const money = (n) => Number(n || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const intf = (n) => Number(n || 0).toLocaleString("en-US", { maximumFractionDigits: 0 });
const hasAr = (s) => /[؀-ۿ]/.test(String(s || ""));
const MONTHS_AR = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
const MONTHS_EN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

/** Gregorian date with Latin digits at Riyadh time (UTC+3, no DST) — no ICU, so it never drifts. */
export function fmtDate(at, l) {
  if (at == null || at === "") return "";
  const d = at instanceof Date ? at : new Date(/^\d{4}-\d{2}-\d{2}$/.test(String(at)) ? `${at}T12:00:00+03:00` : at);
  if (Number.isNaN(d.getTime())) return "";
  const r = new Date(d.getTime() + 3 * 3600e3);
  const day = r.getUTCDate(), m = r.getUTCMonth(), y = r.getUTCFullYear();
  return l === "ar" ? `${day} ${MONTHS_AR[m]} ${y}` : `${day} ${MONTHS_EN[m]} ${y}`;
}

// ───────────────────────────── the company ───────────────────────────────────
let _site = null;
function siteData() {
  if (_site) return _site;
  try {
    const here = dirname(fileURLToPath(import.meta.url));
    _site = JSON.parse(readFileSync(join(here, "..", "site", "data", "site.json"), "utf8"));
  } catch { _site = {}; }
  return _site;
}
const phoneFmt = (p) => { const m = String(p || "").match(/^\+966(\d{2})(\d{3})(\d{4})$/); return m ? `+966 ${m[1]} ${m[2]} ${m[3]}` : String(p || ""); };
const ibanFmt = (s) => String(s || "").replace(/(.{4})/g, "$1 ").trim();

/**
 * The facts printed in the footer, on the signature box and on the back cover — all from the place the
 * site footer reads (site/data/site.json), so the paper can never disagree with the footer. Nothing is
 * invented: an empty field is simply not printed. The API stores this object with the quotation
 * (quote.doc.company) so a later change of address does not rewrite an old quotation.
 */
export function companySnapshotV3() {
  const S = siteData(), L = S.legal || {}, C = S.contact || {};
  return {
    nameAr: LEGAL_NAME || L.name || "شركة بزنس بارتنر سلوشنز",
    nameEn: LEGAL_NAME_EN || L.nameEn || "Business Partner Solutions Company",
    unified: UNIFIED_NUMBER, vat: VAT_NUMBER,
    shortAddress: L.shortAddress || "",
    addrEn: [L.buildingNo && L.streetEn ? `${L.buildingNo} ${L.streetEn}${L.districtEn ? `, ${L.districtEn}` : ""}` : "", [L.cityEn, L.postalCode].filter(Boolean).join(" ") ? `${[L.cityEn, L.postalCode].filter(Boolean).join(" ")}, Saudi Arabia` : ""].filter(Boolean),
    addrAr: [L.buildingNo && L.street ? `${L.buildingNo} ${L.street}${L.district ? `، ${L.district}` : ""}` : "", [L.city, L.postalCode].filter(Boolean).join(" ") ? `${[L.city, L.postalCode].filter(Boolean).join(" ")}، المملكة العربية السعودية` : ""].filter(Boolean),
    phone: phoneFmt(C.phoneIntl), email: C.email || "", website: C.website || "",
    bank: { beneficiaryAr: BANK.beneficiary || "", beneficiaryEn: BANK.beneficiaryEn || "", bankAr: BANK.bank || "", bankEn: BANK.bankEn || "", iban: ibanFmt(BANK.iban) },
    signer: {
      nameAr: env("COMPANY_SIGNER_NAME_AR") || L.signerAr || "باهر بكر علي مقنص", nameEn: env("COMPANY_SIGNER_NAME_EN") || L.signerEn || "Baher Bakr Ali Magnas",
      titleAr: env("COMPANY_SIGNER_TITLE_AR") || "المدير العام", titleEn: env("COMPANY_SIGNER_TITLE_EN") || "General Manager",
    },
  };
}

// ───────────────────────────── the order's lines ─────────────────────────────
const lineTotal = (l) => {
  const q = Number(l.qty) || 1;
  const v = [l.line, l.amount, (Number(l.price) || 0) * q].find((x) => Number(x) > 0);
  return Number(v) || 0;
};
function normLines(items) {
  return (Array.isArray(items) ? items : []).map((it) => {
    const qty = Number(it.qty) || 1;
    const line = round2(lineTotal(it));
    const unit = Number(it.price) > 0 ? round2(Number(it.price)) : round2(line / qty);
    const ar = String(it.title || it.name || "").trim();
    const en = String(it.titleEn || it.nameEn || "").trim();
    return { code: String(it.code || ""), ar, en: en || ar, hasEn: !!en, description: String(it.description || ""), qty, unit, line };
  }).filter((l) => l.ar || l.en);
}
function totalsOf(lines, { net, vat, total, vatRate = 15 } = {}) {
  const sum = round2(lines.reduce((s, l) => s + l.line, 0));
  const ok = (v) => v != null && v !== "" && Number.isFinite(Number(v));
  const n = ok(net) ? round2(Number(net)) : sum;
  const v = ok(vat) ? round2(Number(vat)) : round2(n * Number(vatRate) / 100);
  const t = ok(total) ? round2(Number(total)) : round2(n + v);
  return { sum, net: n, vat: v, total: t, vatRate: Number(vatRate) || 15 };
}
/** A paper with no priced line is not a paper: «0.00» in every cell reads as a real offer. */
function assertOrder(raw, L, { net, vat, total }) {
  const rawCount = Array.isArray(raw) ? raw.length : 0;
  if (!rawCount || !L.length) throw new Error("bp_docs_no_items");
  if (L.length !== rawCount) throw new Error("bp_docs_unnamed_item");
  raw.forEach((r, i) => { if (r && r.qty != null && r.qty !== "" && !(Number(r.qty) > 0)) throw new Error(`bp_docs_bad_line:${i + 1}`); });
  L.forEach((l, i) => { if (!(Number.isFinite(l.line) && l.line > 0) || !(Number.isFinite(l.qty) && l.qty > 0)) throw new Error(`bp_docs_bad_line:${i + 1}`); });
  for (const [k, v] of [["net", net], ["vat", vat], ["total", total]]) {
    if (v == null || v === "") continue;
    if (!Number.isFinite(Number(v)) || Number(v) < 0 || (k !== "vat" && Number(v) === 0)) throw new Error(`bp_docs_bad_total:${k}`);
  }
}

