const FONT_LINK = '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=IBM+Plex+Sans+Arabic:wght@400;700&family=Playfair+Display:wght@700&display=swap">';

// ───────────────────────────── small builders ────────────────────────────────
// A row of two columns: English on the left (LTR), Arabic on the right (RTL).
const rw = (en, ar, cls = "") => `<div class="rw ${cls}"><div class="col" dir="ltr">${en}</div><div class="col" dir="rtl">${ar}</div></div>`;
const h2 = (n, en, ar) => rw(`<h2>${n ? `<span class="n">${n}</span>` : ""}${en}</h2>`, `<h2>${n ? `<span class="n">${n}</span>` : ""}${ar}</h2>`);
// an Arabic sentence ends with its full stop + RLM; a percentage inside it keeps its sign on the right side of the digits
const ar_ = (s) => `${String(s).replace(/(\d+(?:\.\d+)?%)/g, "<bdi>$1</bdi>")}${RLM}`;
const nm = (s) => `<span class="num">${esc(s)}</span>`;
const who = (s) => `<bdi>${esc(s)}</bdi>`;
const th = (html, cls = "") => `<th colspan="1" class="${cls}">${html}</th>`;
const td = (html, cls = "", span = 1) => `<td colspan="${span}" class="${cls}">${html}</td>`;
const GAP = '<td class="gp"></td>';
const colgroup = (ws) => `<colgroup>${ws.map((w) => `<col style="width:${w}%">`).join("")}</colgroup>`;
const tableOpen = (cls, ws, headHtml) => `<table class="pt ${cls}">${colgroup(ws)}<tr>${headHtml}</tr>`;

// ───────────────────────────── page flow ─────────────────────────────────────
// Pages are fixed-size sheets: content must end above the footer (≈ 518px tall area). Heights are
// ESTIMATED from the text length (the server has no browser) with a safety margin; a group of
// blocks that does not fit moves to the next sheet — the font is never shrunk (the standard).
const BUDGET = 512;
const LH = 14.7;
const H = { h2: 34, meta: 24, rowPad: 5.2, head1: 27, head2: 41, sku: 13.4 };
// characters per line (a conservative share of what each column really holds), by column width
const CAP = { note: [94, 102], lt: [94, 102], kv: [66, 68], order: [42, 46], rev: [43, 47], scope: [82, 86] };
const rowH = (lines, extra = 0) => lines * LH + H.rowPad + extra;
const noteH = (en, ar) => Math.max(wrapN(en, CAP.note[0]), wrapN(ar, CAP.note[1])) * LH + 5.2;
const wrapN = (text, cap) => {
  let n = 0;
  for (const part of String(text == null ? "" : text).split(/\n/)) {
    let lines = 1, cur = 0;
    for (const w of part.split(/\s+/)) {
      let len = [...w].length;
      while (len > cap) { if (cur) lines++; cur = 0; len -= cap; lines++; }
      if (cur === 0) cur = len; else if (cur + 1 + len <= cap) cur += 1 + len; else { lines++; cur = len; }
    }
    n += lines;
  }
  return n;
};
/** Packs atomic groups of units into pages. A unit {h, html, table?}; a unit flagged `keep` stays with the next one. */
function pack(units, budget = BUDGET) {
  const groups = []; let cur = [];
  for (const u of units) { cur.push(u); if (!u.keep) { groups.push(cur); cur = []; } }
  if (cur.length) groups.push(cur);
  const pages = []; let page = [], used = 0, open = null;
  const flush = () => { if (page.length) pages.push(page); page = []; used = 0; open = null; };
  for (const g of groups) {
    const cost = (afterBreak) => {
      let c = 0, t = afterBreak ? null : open, first = true;
      for (const u of g) {
        if (u.table && t !== u.table) { c += u.table.headH; if (first && afterBreak && u.table.contH) c += u.table.contH; }
        t = u.table || null; first = false; c += u.h;
      }
      return c;
    };
    if (page.length && used + cost(false) > budget) flush();
    used += cost(!page.length);
    for (const u of g) { page.push(u); open = u.table || null; }
  }
  flush();
  return pages;
}
/** Renders one packed page's units (opening / closing tables and repeating a table's heading when it continues). */
function renderUnits(page) {
  let out = "", t = null, first = true;
  for (const u of page) {
    if (t && t !== u.table) { out += "</table>"; t = null; }
    if (u.table && t !== u.table) { out += (first && u.table.contH ? u.table.contHtml : "") + u.table.open(); t = u.table; }
    out += u.html; first = false;
  }
  if (t) out += "</table>";
  return out;
}
const plainText = (h) => String(h).replace(/<[^>]+>/g, "").replace(/&[a-z]+;/g, "x");
const U = (h, html, extra = {}) => ({ h, html, ...extra });

