const ORDER_W = [25, 6.5, 8.75, 8.75, 2, 8.75, 8.75, 6.5, 25];
function orderTable(L, T, labels) {
  const open = () => tableOpen("", ORDER_W,
    th(labels.first.en, "en") + th(`${labels.qty.en}`, "c en") + th("Unit price<br>(SAR)", "c en") + th("Amount<br>(SAR)", "c en") + GAP
    + th("المبلغ<br>(ريال)", "c ar") + th("سعر الوحدة<br>(ريال)", "c ar") + th(labels.qty.ar, "c ar") + th(labels.first.ar, "ar"));
  const table = { id: "order", headH: H.head2, contH: labels.cont === false ? 0 : H.h2, open, contHtml: labels.cont === false ? "" : h2("", "Price (continued)", "السعر (تابع)") };
  const units = L.map((l, i) => {
    const lines = Math.max(wrapN(l.en, CAP.order[0]), wrapN(l.ar, CAP.order[1]));
    const row = `<tr>${td(`${esc(l.en)}${l.code ? `<span class="num sku">${esc(l.code)}</span>` : ""}`, "en")}${td(nm(intf(l.qty)), "c en")}${td(nm(money(l.unit)), "c en")}${td(nm(money(l.line)), "c en")}${GAP}`
      + `${td(nm(money(l.line)), "c ar")}${td(nm(money(l.unit)), "c ar")}${td(nm(intf(l.qty)), "c ar")}${td(`${esc(l.ar)}${l.code ? `<span class="num sku">${esc(l.code)}</span>` : ""}`, "ar")}</tr>`;
    return U(rowH(lines, l.code ? H.sku : 0), row, { table, keep: i === L.length - 1 });
  });
  const tot = (cls, en, ar, v, keep) => U(rowH(1), `<tr class="${cls}">${td(en, "en", 3)}${td(nm(money(v)), "c en")}${GAP}${td(nm(money(v)), "c ar")}${td(ar, "ar", 3)}</tr>`, { table, keep });
  units.push(tot("tot", "Subtotal (before VAT)", "الإجمالي قبل الضريبة", T.net, true));
  units.push(tot("tot", `VAT ${T.vatRate}%`, `ضريبة القيمة المضافة ${T.vatRate}%`, T.vat, true));
  units.push(tot("grand", "Total incl. VAT", "الإجمالي شامل الضريبة", T.total, false));
  return units;
}

