const LT_W = [4, 45, 2, 45, 4];
function scopeUnits(L, services, startNo = 1) {
  const open = () => tableOpen("lt", LT_W, th("#", "en") + th("Service and scope", "en") + GAP + th("الخدمة والنطاق", "ar") + th("#", "ar"));
  const table = { id: "scope", headH: H.head1, contH: H.h2, open, contHtml: h2("", "Scope (continued)", "النطاق (تابع)") };
  return L.map((l, i) => {
    const sv = (services && services[l.code]) || {};
    const fEn = Array.isArray(sv.featuresEn) ? sv.featuresEn : [], fAr = Array.isArray(sv.featuresAr) ? sv.featuresAr : [];
    const dEn = sv.durationEn ? `Duration: ${sv.durationEn}` : "", dAr = sv.durationAr ? `المدة: ${sv.durationAr}` : "";
    const fallEn = fEn.length ? "" : "Execution of the service as named, as listed in the Business Partner service catalogue.";
    const fallAr = fAr.length ? "" : (sv.descAr || (l.description && !/^السعر شهري|^حدّ أدنى/.test(l.description) ? l.description : "") || "تنفيذ الخدمة بحسب اسمها في كتالوج خدمات Business Partner.");
    const cell = (name, feats, dur, fall, isAr) => `<b>${esc(name)}</b>${l.code ? ` ${nm(l.code)}` : ""}`
      + (feats.length ? `<ul>${feats.map((f) => `<li>${esc(f)}</li>`).join("")}</ul>` : `<br>${esc(fall)}`)
      + (dur ? `<p class="mu">${esc(dur)}</p>` : "");
    const cEn = cell(l.en, fEn, dEn, fallEn, false), cAr = cell(l.ar, fAr, dAr, fallAr, true);
    const ln = (feats, dur, fall, name, cap) => wrapN(name, cap) + (feats.length ? feats.reduce((s, f) => s + wrapN(f, cap - 8), 0) : wrapN(fall, cap)) + (dur ? wrapN(dur, cap) : 0);
    const lines = Math.max(ln(fEn, dEn, fallEn, l.en, CAP.scope[0]), ln(fAr, dAr, fallAr, l.ar, CAP.scope[1]));
    const extra = 2.5 + Math.max(fEn.length, fAr.length) * 1.4;
    const row = `<tr>${td(nm(String(startNo + i)), "en")}${td(cEn, "en")}${GAP}${td(cAr, "ar")}${td(nm(String(startNo + i)), "ar")}</tr>`;
    return U(rowH(lines, extra), row, { table });
  });
}

